<?php
declare(strict_types=1);

function answer_split_raw(string $raw): array {
    // Only split the complete metadata suffix generated by our API adapters.
    $pattern = '~\n\nAIが生成した検索クエリ\n(.*?)\n\n参照したURL\n(.*?)\n\n回答で実際に引用したURL\n(.*)\z~s';
    if (!preg_match($pattern, $raw, $match, PREG_OFFSET_CAPTURE)) return [$raw, []];
    $info = [];
    foreach (['検索クエリ', '参照したURL', '回答で引用したURL'] as $i => $label) {
        $values = array_values(array_filter(explode("\n", trim($match[$i+1][0])), static fn($s) => trim($s) !== '' && trim($s) !== '（取得なし）'));
        $info[$label] = $values;
    }
    return [substr($raw, 0, $match[0][1]), $info];
}
